do $guard$ begin
 if (select count(*) from vinyl_gift_updates)<>32 or
    (select count(*) from catalog_items c join vinyl_gift_updates v on c.stable_id=v.id
      where c.metadata->>'friendId'='adventure_friend_hz' and c.metadata->>'giftCategoryCode'='C15'
        and 'adventure_v2_gift'=any(c.tags))<>32 then
   raise exception 'Hazel gift catalog mismatch; no data changed';
 end if;
end $guard$;
update public.catalog_items c set title=v.title,asset=v.asset,
 metadata=c.metadata||'{"giftCategory":"Vinyl"}'::jsonb,updated_at=now()
from vinyl_gift_updates v where c.stable_id=v.id
 and (c.title is distinct from v.title or c.asset is distinct from v.asset or c.metadata->>'giftCategory' is distinct from 'Vinyl');
-- Reserved/current/completed encounters retain their choices, reward IDs and claim state.
-- Only the three presentation fields inside the existing gift snapshot are refreshed.
update public.adventure_encounter_plans p set snapshot=jsonb_set(p.snapshot,'{giftSnapshot}',
 (p.snapshot->'giftSnapshot')||jsonb_build_object('title',v.title,'asset',v.asset,
 'metadata',coalesce(p.snapshot->'giftSnapshot'->'metadata','{}'::jsonb)||'{"giftCategory":"Vinyl"}'::jsonb))
from vinyl_gift_updates v where p.gift_id=v.id and p.snapshot->'giftSnapshot'->>'stable_id'=v.id;
update public.adventure_results r set metadata=jsonb_set(r.metadata,'{giftSnapshot}',
 (r.metadata->'giftSnapshot')||jsonb_build_object('title',v.title,'asset',v.asset,
 'metadata',coalesce(r.metadata->'giftSnapshot'->'metadata','{}'::jsonb)||'{"giftCategory":"Vinyl"}'::jsonb))
from vinyl_gift_updates v where r.metadata->'giftSnapshot'->>'stable_id'=v.id;
commit;
